    fr: { "home.lead": "PflegeDoc transforme vos notes – saisies ou dictées, dans n'importe quelle langue – en une documentation de soins allemande professionnelle et une planification des soins selon les standards en vigueur en Allemagne (NRW). Vous vérifiez et assumez chaque résultat.", "home.b1": "Dicter ou taper – dans n'importe quelle langue", "home.b2": "Documentation de suivi et planification des soins par patient", "home.b3": "Historique personnel, stocké en sécurité", "home.doc.desc": "Ce qui a été fait avec le patient – par service ou par heure.", "home.plan.desc": "Un projet par patient : problèmes, objectifs, interventions.", "home.settings.desc": "Compte, langue, apparence, saisie vocale." },
    es: { "home.lead": "PflegeDoc convierte tus notas – escritas o dictadas, en cualquier idioma – en una documentación de cuidados en alemán profesional y una planificación de cuidados según los estándares de Alemania (NRW). Tú revisas y respondes por cada resultado.", "home.b1": "Dictar o escribir – en cualquier idioma", "home.b2": "Documentación de evolución y planificación de cuidados por paciente", "home.b3": "Historial personal, guardado de forma segura", "home.doc.desc": "Lo que se hizo con el paciente – por turno u hora.", "home.plan.desc": "Un proyecto por paciente: problemas, objetivos, medidas.", "home.settings.desc": "Cuenta, idioma, apariencia, entrada de voz." },
    it: { "home.lead": "PflegeDoc trasforma i tuoi appunti – digitati o dettati, in qualsiasi lingua – in una documentazione infermieristica tedesca professionale e in una pianificazione assistenziale secondo gli standard in vigore in Germania (NRW). Tu verifichi e ti assumi la responsabilità di ogni risultato.", "home.b1": "Dettare o digitare – in qualsiasi lingua", "home.b2": "Documentazione di decorso e pianificazione assistenziale per paziente", "home.b3": "Cronologia personale, archiviata in sicurezza", "home.doc.desc": "Cosa è stato fatto con il paziente – per turno o orario.", "home.plan.desc": "Un progetto per paziente: problemi, obiettivi, interventi.", "home.settings.desc": "Account, lingua, aspetto, input vocale." },
    pt: { "home.lead": "O PflegeDoc transforma as tuas notas – escritas ou ditadas, em qualquer idioma – numa documentação de cuidados alemã profissional e num planeamento de cuidados segundo os padrões usados na Alemanha (NRW). Tu verificas e assumes cada resultado.", "home.b1": "Ditar ou escrever – em qualquer idioma", "home.b2": "Documentação de evolução e planeamento de cuidados por paciente", "home.b3": "Histórico pessoal, guardado em segurança", "home.doc.desc": "O que foi feito com o paciente – por turno ou hora.", "home.plan.desc": "Um projeto por paciente: problemas, objetivos, medidas.", "home.settings.desc": "Conta, idioma, aparência, entrada de voz." },
    pl: { "home.lead": "PflegeDoc zamienia Twoje notatki – wpisane lub podyktowane, w dowolnym języku – w profesjonalną niemiecką dokumentację opieki i plan opieki zgodny ze standardami obowiązującymi w Niemczech (NRW). Ty sprawdzasz i odpowiadasz za każdy wynik.", "home.b1": "Dyktuj lub pisz – w dowolnym języku", "home.b2": "Dokumentacja przebiegu i planowanie opieki dla każdego pacjenta", "home.b3": "Osobista historia, bezpiecznie przechowywana", "home.doc.desc": "Co zrobiono z pacjentem – na zmianę lub o danej godzinie.", "home.plan.desc": "Jeden projekt na pacjenta: problemy, cele, działania.", "home.settings.desc": "Konto, język, wygląd, wprowadzanie głosowe." },
